import re

class _Rules(Rules):
    DOSE = __DOSE__

    TARGET_HINTS = {
        'go to microwave 1': 'the potato is here',
        'open microwave 1': 'the potato is inside',
        'take potato 1 from microwave 1': 'take the potato',
    }

    def _annotate(self, cmds):
        if self.DOSE <= 0:
            return list(cmds)
        out = []
        hinted = []
        for c in cmds:
            key = c.strip()
            if key in self.TARGET_HINTS and self.DOSE > 0:
                hinted.append((key, self.TARGET_HINTS[key]))
            else:
                out.append(c)
        # Surface hinted commands at the top, annotated with a salient hint.
        for key, hint in hinted:
            out.insert(0, f'{key}  [hint: {hint}]')
        return out

    def filter_observation(self, obs, env_state):
        cmds = obs.data.get('admissible_commands')
        if cmds is None:
            return obs
        new_cmds = self._annotate(list(cmds))
        new_text = obs.text
        # Rewrite the 'Admissible commands:' section to match the reordered list
        # so text and structured data stay consistent for the policy.
        m = re.search(r'Admissible commands:.*', new_text, re.DOTALL)
        if m:
            new_text = new_text[:m.start()] + 'Admissible commands: ' + ', '.join(new_cmds)
        return Observation(text=new_text, data=dict(obs.data, admissible_commands=new_cmds))

import re

class _Rules(Rules):
    DOSE = __DOSE__

    def _goal_mentions_butterknife(self, env_state):
        return 'butterknife' in (env_state.goal_text or '').lower()

    def filter_observation(self, obs, env_state):
        if not self._goal_mentions_butterknife(env_state):
            return obs
        text = obs.text
        data = obs.data
        cmds = list(data.get('admissible_commands') or []) if data else []

        # DOSE == 0: unchanged
        if self.DOSE <= 0.0:
            return obs

        hint = "Hint: the butterknife is on a countertop (try countertop 2)."

        # Add the hint into the observation text at increasing salience.
        if self.DOSE < 0.5:
            if 'Hint:' not in text:
                text = text.rstrip() + '\n\n' + hint
        else:
            # Stronger: put the hint right after the task line.
            lines = text.split('\n')
            if lines and lines[0].startswith('Task:'):
                if 'Hint:' not in lines[0]:
                    lines[0] = lines[0] + '  ' + hint
                    text = '\n'.join(lines)
            elif 'Hint:' not in text:
                text = text.rstrip() + '\n\n' + hint

        # Reorder admissible commands to promote 'go to countertop 2'.
        target = 'go to countertop 2'
        if target in cmds:
            cmds.remove(target)
            cmds.insert(0, target)

        new_data = dict(data) if data else {}
        new_data['admissible_commands'] = cmds
        return Observation(text=text, data=new_data)
